  if(!party.city)addMissing('Party city / place','Enter the recipient city in Parties master.','Parties');
  if(!party.state)addMissing('Party state','Select the recipient state in Parties master.','Parties');
  if(!/^\d{6}$/.test(String(party.pincode||'')))addMissing('Party PIN code','Enter a valid 6-digit PIN in Parties master.','Parties');
