function renderMasterRows(key,query){const cfg=Object.values(masterConfigs).find(c=>c.key===key),q=(query||'').trim().toLowerCase();return masterRows(key).filter(row=>JSON.stringify(row).toLowerCase().includes(q)).map(row=>`<tr><td>${cfg.columns.map((col,index)=>`<div class="master-cell ${index===0?'master-primary':''}">${index===0?`<span class="master-avatar">${escapeHtml(String(row[col[0]]||'?').slice(0,2).toUpperCase())}</span>`:''}<span>${escapeHtml(Array.isArray(row[col[0]])?row[col[0]].join(', '):row[col[0]]||'—')}${col[0]==='state'&&row.state?' · '+escapeHtml(stateOptions.find(s=>s[0]===row.state)?.[1]||''):''}</span></div>`).join('</td><td>')}</td><td><div class="master-row-actions"><button type="button" onclick="editMaster('${key}','${row.id}')">Edit</button><button type="button" class="delete-action" onclick="deleteMaster('${key}','${row.id}')">Delete</button></div></td></tr>`).join('')||`<tr><td class="master-no-results" colspan="${cfg.columns.length+1}">No matching records found.</td></tr>`}
